import json


def _ptr(path):
    return ''.join('/' + str(x).replace('~', '~0').replace('/', '~1') for x in path)


def _equal(a, b):
    # JSON booleans are distinct from numbers even though Python bool subclasses int.
    if isinstance(a, bool) or isinstance(b, bool):
        return type(a) is type(b) and a == b
    if isinstance(a, (int, float)) and isinstance(b, (int, float)):
        return a == b
    if type(a) is not type(b):
        return False
    if isinstance(a, dict):
        return a.keys() == b.keys() and all(_equal(a[k], b[k]) for k in a)
    if isinstance(a, list):
        return len(a) == len(b) and all(_equal(x, y) for x, y in zip(a, b))
    return a == b


def generate_patch(before, after):
    """Return operations generated by jd's -f patch mode.

    Changed scalar values use a guarded remove/add pair. Object changes recurse,
    while arrays are conservatively replaced at changed indices.
    """
    ops = []

    def emit(op, path, value=None, include=True):
        d = {'op': op, 'path': _ptr(path)}
        if include:
            d['value'] = value
        ops.append(d)

    def walk(a, b, path):
        if _equal(a, b):
            return
        if isinstance(a, dict) and isinstance(b, dict):
            # Preserve source insertion order, followed by target insertion order.
            for k in a:
                if k not in b:
                    emit('test', path + [k], a[k])
                    emit('remove', path + [k], a[k])
            for k in b:
                if k not in a:
                    emit('add', path + [k], b[k])
                else:
                    walk(a[k], b[k], path + [k])
            return
        if isinstance(a, list) and isinstance(b, list):
            # Keep identical prefix and suffix, adjusting changed middle ranges.
            lo = 0
            while lo < min(len(a), len(b)) and type(a[lo]) is type(b[lo]) and _equal(a[lo], b[lo]):
                lo += 1
            hi = 0
            while hi < len(a)-lo and hi < len(b)-lo and type(a[-1-hi]) is type(b[-1-hi]) and _equal(a[-1-hi], b[-1-hi]):
                hi += 1
            oldmid = a[lo:len(a)-hi if hi else len(a)]
            newmid = b[lo:len(b)-hi if hi else len(b)]
            # Guard one boundary element on each side, then each changed value.
            # This is the structural patcher's context protection for list edits.
            if lo:
                emit('test', path + [lo-1], a[lo-1])
            if hi:
                emit('test', path + [lo+len(oldmid)], a[lo+len(oldmid)])
            for i, v in enumerate(oldmid):
                emit('test', path + [lo+i], v)
            for i in range(len(oldmid)-1, -1, -1):
                emit('remove', path + [lo+i], oldmid[i])
            for i in range(len(newmid)):
                emit('add', path + [lo+i], newmid[i])
            return
        emit('test', path, a)
        emit('remove', path, a)
        emit('add', path, b)

    walk(before, after, [])
    return ops


