"""RFC 6902 patch application helpers.

The CLI layer can call apply_patch(document, operations) after decoding JSON.
"""
import copy


def _parts(path):
    if path == "":
        return []
    if not isinstance(path, str) or not path.startswith("/"):
        raise ValueError("invalid JSON Pointer")
    return [p.replace("~1", "/").replace("~0", "~") for p in path[1:].split("/")]


def _parent(doc, parts):
    cur = doc
    for part in parts[:-1]:
        if isinstance(cur, list):
            cur = cur[int(part)]
        else:
            cur = cur[part]
    return cur


def _get(doc, parts):
    cur = doc
    for part in parts:
        cur = cur[int(part)] if isinstance(cur, list) else cur[part]
    return cur


def _equal(left, right):
    # Python considers True equal to 1; JSON does not.
    if isinstance(left, bool) or isinstance(right, bool):
        return type(left) is type(right) and left == right
    if isinstance(left, dict) and isinstance(right, dict):
        return left.keys() == right.keys() and all(_equal(left[k], right[k]) for k in left)
    if isinstance(left, list) and isinstance(right, list):
        return len(left) == len(right) and all(_equal(a, b) for a, b in zip(left, right))
    return left == right


def apply_patch(document, operations):
    """Apply the add and guarded remove operations used by jd patch files."""
    doc = copy.deepcopy(document)
    # jd's patch dialect uses tests as guards for removes; tests can also guard
    # neighboring array context, so the corresponding remove need not be adjacent.
    for number, operation in enumerate(operations):
        if operation.get("op") == "test" and not any(
            later.get("op") in ("remove", "add")
            for later in operations[number + 1:]
        ):
            raise ValueError("JSON Patch test op must be followed by a remove or add op")
    for number, operation in enumerate(operations):
        op = operation["op"]
        path = _parts(operation["path"])
        if op == "test":
            if not _equal(_get(doc, path), operation.get("value")):
                raise ValueError("test operation failed")
            continue
        if op == "remove":
            if not any(
                earlier.get("op") == "test" and earlier.get("path") == operation.get("path")
                for earlier in operations[:number]
            ):
                raise ValueError("invalid JSON Patch: remove must follow test")
            if not path:
                doc = None
            else:
                par = _parent(doc, path)
                key = path[-1]
                if isinstance(par, list):
                    del par[int(key)]
                else:
                    del par[key]
            continue
        if op != "add":
            raise ValueError("invalid JSON Patch: must be test/remove or add ops")
        if path:
            par = _parent(doc, path)
            if isinstance(par, dict) and path[-1] in par:
                raise ValueError("add path already exists")
        elif number != 0 and not any(
            earlier.get("op") == "remove" and earlier.get("path") == ""
            for earlier in operations[:number]
        ):
            raise ValueError("root add must be the only operation")
        if op in ("move", "copy"):
            value = copy.deepcopy(_get(doc, _parts(operation["from"])))
            if op == "move":
                src = _parts(operation["from"])
                if not src:
                    doc = None
                else:
                    par = _parent(doc, src)
                    if isinstance(par, list):
                        del par[int(src[-1])]
                    else:
                        del par[src[-1]]
            operation_value = value
        elif op in ("add", "replace"):
            operation_value = copy.deepcopy(operation["value"])
        else:
            raise ValueError("unsupported operation")
        if not path:
            if op == "remove":
                doc = None
            else:
                doc = operation_value
            continue
        parent = _parent(doc, path)
        key = path[-1]
        if isinstance(parent, list):
            if op == "add" or op in ("move", "copy"):
                index = len(parent) if key == "-" else int(key)
                parent.insert(index, operation_value)
            elif op == "remove":
                del parent[int(key)]
            else:
                parent[int(key)] = operation_value
        elif op == "remove":
            del parent[key]
        else:
            parent[key] = operation_value
    return doc
